parameters.functionCode:
// Aggregate incident frequency and determine risk escalation
const item = $input.first().json.body;
return [{
  json: {
    zone: item.zone,
    total_incidents: item.incident_count,
    requires_facility_intervention: item.incident_count >= 3,
    pattern: item.pattern
  }
}];

parameters.description:
Recurring safety violations detected by Hack-Eye Swarm Node.
Pattern: {{ $json.pattern }}
Recorded incidents: {{ $json.total_incidents }}
Required Action: Install acoustic warning sensors and floor markings.
